// A definição real, em lib.es5.d.ts, é uma linha:
//   type Partial<T>  = { [P in keyof T]?: T[P] };
//   type Required<T> = { [P in keyof T]-?: T[P] };
//   type Readonly<T> = { readonly [P in keyof T]: T[P] };

// O mesmo mapped type escrito à mão no módulo anterior:
type TudoOpcional<T> = { [K in keyof T]?: T[K] };

interface Livro {
  titulo: string;
  paginas: number;
}

// Os dois tipos são o mesmo tipo: o valor passa de um lado para o outro sem conversão.
const escrito: TudoOpcional<Livro> = { titulo: "TypeScript de A a Z" };
const daBiblioteca: Partial<Livro> = escrito;
const devolta: TudoOpcional<Livro> = daBiblioteca;

console.log(devolta.titulo); // TypeScript de A a Z
console.log(devolta.paginas); // undefined

interface Utilizador {
  id: number;
  nome: string;
  email: string;
  ativo: boolean;
}

function atualizar(atual: Utilizador, alteracoes: Partial<Utilizador>): Utilizador {
  return { ...atual, ...alteracoes };
}

const ana: Utilizador = { id: 1, nome: "Ana", email: "ana@exemplo.pt", ativo: true };

const anaNova = atualizar(ana, { email: "ana.silva@exemplo.pt" });
console.log(anaNova.email); // ana.silva@exemplo.pt
console.log(anaNova.nome); // Ana

// Construção por etapas: começa vazio e vai enchendo.
const rascunho: Partial<Utilizador> = {};
rascunho.nome = "Rui";
rascunho.id = 2;
console.log(rascunho.nome); // Rui
console.log(rascunho.email); // undefined

// @ts-expect-error o Partial torna opcionais as chaves que existem, não aceita chaves novas
atualizar(ana, { telemovel: "912345678" });

interface Encomenda {
  id: number;
  cliente: string;
  total: number;
}

function aplicar(base: Encomenda, campos: Partial<Encomenda>): Encomenda {
  return { ...base, ...campos };
}

const original: Encomenda = { id: 7, cliente: "Ana", total: 100 };

// O formulário não trouxe nada. O tipo aceita, o compilador cala-se.
const doFormulario: Partial<Encomenda> = {};
const resultado = aplicar(original, doFormulario);
console.log(resultado.total); // 100

// Quem quiser garantir que veio alguma coisa tem de o verificar em tempo de execução.
function temAlgumCampo(campos: Partial<Encomenda>): boolean {
  return Object.keys(campos).length > 0;
}
console.log(temAlgumCampo(doFormulario)); // false
console.log(temAlgumCampo({ total: 90 })); // true

const parcial: Partial<Encomenda> = { id: 9 };
// @ts-expect-error o caminho inverso não existe: um Partial não serve como Encomenda
const completa: Encomenda = parcial;
console.log(completa.id); // 9

interface Definicoes {
  tema?: string;
  idioma?: string;
  notificacoes: boolean | undefined;
}

type DefinicoesCompletas = Required<Definicoes>;
// tema: string
// idioma: string
// notificacoes: boolean | undefined

const d: DefinicoesCompletas = {
  tema: "escuro",
  idioma: "pt-PT",
  notificacoes: undefined,
};
console.log(d.tema.length); // 6

// @ts-expect-error tema era opcional, por isso o -? tirou-lhe também o undefined
const d2: DefinicoesCompletas = { tema: undefined, idioma: "pt-PT", notificacoes: true };
console.log(d2.idioma); // pt-PT

// @ts-expect-error com Required todas as chaves passam a ser obrigatórias
const d3: DefinicoesCompletas = { tema: "claro", idioma: "pt-PT" };
console.log(d3.tema); // claro

interface Ponto {
  x: number;
  y: number;
}

const mutavel: Ponto = { x: 1, y: 2 };
const selado: Readonly<Ponto> = mutavel;

// @ts-expect-error o compilador recusa a escrita numa propriedade readonly
selado.x = 99;

// A marca readonly desaparece na compilação: o JavaScript emitido faz a atribuição.
console.log(mutavel.x); // 99
console.log(selado.x); // 99

// Para travar a escrita em tempo de execução é preciso Object.freeze.
const congelado: Readonly<Ponto> = Object.freeze({ x: 1, y: 2 });
try {
  (congelado as Ponto).y = 50;
} catch (erro) {
  console.log("recusado em runtime");
}
console.log(congelado.y); // 2

interface Servidor {
  host: string;
  limites: { maxLigacoes: number };
}

const base: Servidor = { host: "localhost", limites: { maxLigacoes: 10 } };
const so: Readonly<Servidor> = base;

// @ts-expect-error host é readonly ao primeiro nível
so.host = "outro";

// limites é readonly, mas o objeto para onde aponta não é: isto compila.
so.limites.maxLigacoes = 99;
console.log(base.limites.maxLigacoes); // 99

// O mesmo com Partial: o ? ficou-se pelo primeiro nível.
const p: Partial<Servidor> = { limites: { maxLigacoes: 1 } };
console.log(p.host); // undefined

const q: Partial<Servidor> = {
  // @ts-expect-error maxLigacoes continua obrigatória dentro de limites
  limites: {},
};
console.log(q.limites); // {}

interface Opcoes {
  baseUrl: string;
  timeoutMs: number;
  tentativas: number;
}

const POR_OMISSAO: Readonly<Opcoes> = {
  baseUrl: "https://api.exemplo.pt",
  timeoutMs: 5000,
  tentativas: 3,
};

function criarOpcoes(dadas: Partial<Opcoes> = {}): Readonly<Opcoes> {
  return { ...POR_OMISSAO, ...dadas };
}

const padrao = criarOpcoes();
console.log(padrao.timeoutMs); // 5000

const rapido = criarOpcoes({ timeoutMs: 1000 });
console.log(rapido.timeoutMs); // 1000
console.log(rapido.baseUrl); // https://api.exemplo.pt

// @ts-expect-error o resultado sai selado
rapido.tentativas = 10;

// Cuidado: undefined escrito à mão passa pelo Partial e apaga o valor por omissão.
const estragado = criarOpcoes({ timeoutMs: undefined });
console.log(estragado.timeoutMs); // undefined

