interface Artigo {
  id: number;
  titulo: string;
  preco: number;
  stock: number;
}

function editarArtigo(artigo: Artigo, alteracoes: Partial<Artigo>): Artigo {
  return { ...artigo, ...alteracoes };
}

const teclado: Artigo = { id: 1, titulo: "Teclado", preco: 49.9, stock: 12 };

const emSaldo = editarArtigo(teclado, { preco: 39.9 });
console.log(emSaldo.preco); // 39.9
console.log(emSaldo.titulo); // Teclado

const reposto = editarArtigo(teclado, { stock: 30, preco: 45 });
console.log(reposto.stock); // 30

// O original fica intacto porque a função devolve um objeto novo.
console.log(teclado.preco); // 49.9

interface PedidoRelatorio {
  formato?: string;
  incluirGraficos?: boolean;
  maxLinhas?: number;
}

function normalizar(pedido: PedidoRelatorio): Required<PedidoRelatorio> {
  return {
    formato: pedido.formato ?? "pdf",
    incluirGraficos: pedido.incluirGraficos ?? false,
    maxLinhas: pedido.maxLinhas ?? 1000,
  };
}

const vazio = normalizar({});
console.log(vazio.formato); // pdf
console.log(vazio.maxLinhas); // 1000
console.log(vazio.incluirGraficos); // false

const escolhido = normalizar({ formato: "csv", maxLinhas: 50 });
console.log(escolhido.formato); // csv
console.log(escolhido.maxLinhas); // 50
console.log(escolhido.incluirGraficos); // false

// Depois de Required, o compilador já não obriga a verificar undefined.
console.log(escolhido.formato.toUpperCase()); // CSV

interface Equipa {
  nome: string;
  treinador: { nome: string; anos: number };
}

const equipa: Equipa = {
  nome: "Azuis",
  treinador: { nome: "Ana", anos: 5 },
};

const selada: Readonly<Equipa> = equipa;

// @ts-expect-error o primeiro nível está protegido pelo compilador
selada.nome = "Verdes";

// O segundo nível não: isto compila e altera mesmo o objeto.
selada.treinador.anos = 6;
console.log(equipa.treinador.anos); // 6

// Para proteger os dois níveis é preciso aplicar Readonly também por dentro.
type EquipaSelada = Readonly<{
  nome: string;
  treinador: Readonly<{ nome: string; anos: number }>;
}>;

const mesmo: EquipaSelada = equipa;
// @ts-expect-error agora também o segundo nível é recusado pelo compilador
mesmo.treinador.anos = 7;
console.log(equipa.treinador.anos); // 7

interface Ligacao {
  host: string;
  porta: number;
  utilizador: string;
}

function estaCompleta(parcial: Partial<Ligacao>): parcial is Required<Ligacao> {
  return (
    parcial.host !== undefined &&
    parcial.porta !== undefined &&
    parcial.utilizador !== undefined
  );
}

type Passo = (atual: Partial<Ligacao>) => Partial<Ligacao>;

function construir(passos: Passo[]): Readonly<Ligacao> {
  let acumulado: Partial<Ligacao> = {};
  for (const passo of passos) {
    acumulado = { ...acumulado, ...passo(acumulado) };
  }
  if (!estaCompleta(acumulado)) {
    throw new Error("Configuração incompleta");
  }
  return acumulado;
}

const ligacao = construir([
  () => ({ host: "db.exemplo.pt" }),
  () => ({ porta: 5432 }),
  (atual) => ({ utilizador: atual.host === "db.exemplo.pt" ? "admin" : "convidado" }),
]);

console.log(ligacao.host); // db.exemplo.pt
console.log(ligacao.utilizador); // admin

// @ts-expect-error o resultado sai selado como Readonly
ligacao.porta = 1;

try {
  construir([() => ({ host: "so-isto" })]);
} catch (erro) {
  console.log((erro as Error).message); // Configuração incompleta
}
